const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], C = tok[1];
const h = tok.slice(2, 2 + n);
const M = new Array(n), B = new Array(n);
let head = 0, tail = 0;
const val = (i, x) => M[i] * x + B[i];
const useless = (a, b, c) => (B[c] - B[a]) * (M[a] - M[b]) <= (B[b] - B[a]) * (M[a] - M[c]);
M[0] = -2 * h[0]; B[0] = h[0] * h[0]; tail = 1;
let dp = 0;
for (let i = 1; i < n; i++) {
  const x = h[i];
  while (tail - head >= 2 && val(head, x) >= val(head + 1, x)) head++;
  dp = val(head, x) + x * x + C;
  M[tail] = -2 * x; B[tail] = dp + x * x;
  while (tail - head >= 2 && useless(tail - 2, tail - 1, tail)) { M[tail - 1] = M[tail]; B[tail - 1] = B[tail]; tail--; }
  tail++;
}
console.log(String(dp));

