import java.io.*;
import java.util.*;

public class Main {
    static long[] M, B;
    static long val(int i, long x) { return M[i] * x + B[i]; }
    static boolean useless(int a, int b, int c) { return (B[c] - B[a]) * (M[a] - M[b]) <= (B[b] - B[a]) * (M[a] - M[c]); }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long C = (long) in.nval;
        long[] h = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); h[i] = (long) in.nval; }
        M = new long[n];
        B = new long[n];
        int head = 0, tail = 1;
        M[0] = -2 * h[0]; B[0] = h[0] * h[0];
        long dp = 0;
        for (int i = 1; i < n; i++) {
            long x = h[i];
            while (tail - head >= 2 && val(head, x) >= val(head + 1, x)) head++;
            dp = val(head, x) + x * x + C;
            M[tail] = -2 * x; B[tail] = dp + x * x;
            while (tail - head >= 2 && useless(tail - 2, tail - 1, tail)) { M[tail - 1] = M[tail]; B[tail - 1] = B[tail]; tail--; }
            tail++;
        }
        System.out.println(dp);
    }
}

