#include <bits/stdc++.h>
using namespace std;

vector<long long> M, B;
long long val(int i, long long x) { return M[i] * x + B[i]; }
bool useless(int a, int b, int c) { return (B[c] - B[a]) * (M[a] - M[b]) <= (B[b] - B[a]) * (M[a] - M[c]); }

int main() {
    int n;
    long long C;
    scanf("%d %lld", &n, &C);
    vector<long long> h(n);
    for (auto& x : h) scanf("%lld", &x);
    M.assign(n, 0);
    B.assign(n, 0);
    int head = 0, tail = 1;
    M[0] = -2 * h[0]; B[0] = h[0] * h[0];
    long long dp = 0;
    for (int i = 1; i < n; i++) {
        long long x = h[i];
        while (tail - head >= 2 && val(head, x) >= val(head + 1, x)) head++;
        dp = val(head, x) + x * x + C;
        M[tail] = -2 * x; B[tail] = dp + x * x;
        while (tail - head >= 2 && useless(tail - 2, tail - 1, tail)) { M[tail - 1] = M[tail]; B[tail - 1] = B[tail]; tail--; }
        tail++;
    }
    printf("%lld\n", dp);
    return 0;
}
